    "explanation": "全一次空気式（完全予混合式）は理論燃焼に必要な空気量の全量をあらかじめガスと混合したうえで燃焼させる方式。混合が均一なため完全燃焼しやすく炎は短く青い。家庭用こんろのブンゼン式バーナーに近い概念として位置づけられる。\n\nB：燃焼空気の一部を事前混合し残りを周囲から取り込む方式は「部分予混合式（ブンゼン式）」の説明。ブンゼン式は一次空気率が小さく二次空気を利用する。\nC：空気を事前混合せず拡散・混合しながら燃焼する方式は「拡散燃焼式（拡散火炎式）」の説明。炎が長く赤橙色〜黄色になりやすい。\nD：FE式（強制排気式）は排気方式の分類であり、燃焼空気の混合方式の分類とは別の概念。\n\n【頻出】燃焼方式の3分類（全一次空気式・ブンゼン式・拡散式）と各方式の炎の色・特徴は試験頻出事項。\n【混同注意】燃焼方式（予混合・拡散）と給排気方式（CF・FE・FF等）は独立した分類軸であり、混同しないこと。"
