    "answer": 2,
    "explanation": "FF式（Forced Flue：強制給排気式）は給気・排気ともに屋外と専用の給排気管（同軸二重管等）を通じてファンで強制的に行う密閉式燃焼方式。室内空気を一切燃焼に使用しないため、密閉した室内でも安全に使用でき、室内の酸素濃度低下・CO中毒のリスクがない。\n\nA：室内空気を使用し排気を自然対流で屋外排出する方式は「CF式（自然排気式）」の説明。\nB：屋外排気管を持たず室内に排気する方式は「開放式（GF式）」の説明。室内に排気ガスが放出されるため換気が必須。\nD：室内空気を燃焼用に使用しファンで強制排気する方式は「FE式（強制排気式）」の説明。給気は室内空気を使用する点でFF式と異なる。\n\n【頻出】給排気方式の分類（開放式GF・自然排気CF・強制排気FE・強制給排気FF・バランス式BF）の特徴と安全性の違いは試験頻出事項。\n【混同注意】FF式とFE式の違い（FF＝給排気両方屋外、FE＝排気のみ強制・給気は室内）を確実に区別する。"
