    "explanation": "OD装置（Oxygen Depletion Device：酸素欠乏安全装置）は、室内の酸素濃度が燃焼継続に伴い低下した場合（換気不足等）にガス供給を自動遮断する安全装置。室内空気を燃焼用に使用する開放式・半密閉式（CF式等）機器に設置が義務付けられている。\n\nB：OD装置は室内酸素濃度の低下を検知するものであり、排気温度上昇を検知する過熱防止装置とは全く異なる機能・原理の装置。\nC：密閉式（FF式・BF式）機器は室内空気を燃焼に使用しないため酸欠状態にならず、OD装置の設置対象ではない。\nD：OD装置が作動した場合は、機器の点検・換気確認が必要であり、単純な換気後の自動復帰を前提とした点検不要という考え方は安全上誤り。\n\n【頻出】OD装置の設置対象（開放式・半密閉式機器）と作動条件（酸素濃度低下）は試験頻出の安全装置問題。\n【混同注意】OD装置（酸素不足検知）と立消え安全装置（炎の消滅検知）・過熱防止装置（温度上昇検知）はそれぞれ異なる安全機能を持つ装置。"
