    "explanation": "給湯器の凍結防止装置は、外気温が一定以下（約3〜5℃以下等）に低下した場合に自動的に作動する電気ヒーター（配管加熱）または自動水抜き弁（配管内の水を排出）等により、熱交換器・配管内の水の凍結を防ぐ機能を持つ装置。電源が必要な機能。\n\nA：凍結防止のためにガスを燃焼させ続ける方式は一般的な家庭用給湯器では採用されていない。電気ヒーターや水抜きによる凍結防止が主流。\nC：極端な低温（−15℃以下等）や長時間の停電時等の条件では、凍結防止装置があっても凍結する可能性がある。「いかなる低温でも凍結しない」は誤り。\nD：凍結防止装置は長期不使用に限らず、一時的な低温でも自動的に作動する温度検知式の装置。\n\n【頻出】凍結防止装置の作動条件（外気温低下・自動作動）・電源必要性・凍結防止の限界は試験頻出知識。\n【混同注意】凍結防止のために電源（コンセント）が必要な点は見落としやすい。冬季の長期不在前には電源確保または水抜き対応が必要。"
