    "explanation": "二重安全機構（フェイルセーフ設計）は、立消え安全装置（炎検知）＋過熱防止装置（温度検知）のように、異なる原理・方式の安全装置を組み合わせて設置することで、一方の安全装置が故障・誤動作しても別の安全機能が事故を防止できるよう設計された考え方。\n\nA：同種の安全装置を2台並列設置することは「冗長設計（リダンダンシー）」に相当し、異なる原理の組み合わせによる二重安全とは概念が異なる。\nC：二重安全機構の考え方は家庭用ガス機器にも広く採用されており（Siセンサー＋立消え安全装置等）、業務用のみに限定されない。\nD：安全装置が1つ故障した場合でも別の安全装置が機能するというのが二重安全の目的だが、「法令上の保安基準を完全に満たし続ける」とは必ずしも言い切れず、故障した安全装置の修理・交換は必要。\n\n【頻出】二重安全機構の概念（異なる原理の安全装置の組み合わせ）はガス機器安全設計の基本思想として試験に出題される。\n【混同注意】「並列同種装置（冗長性）」と「異種装置の組み合わせ（二重安全）」を区別することが理解のポイント。"
