"answer": 1,
"explanation": "ガス事業法第160条により、消費機器が技術基準に適合しないと判断した場合、一般ガス導管事業者はまず需要家に対してその旨を告知し、修理・改善等の必要な措置をとるよう促さなければならない。直ちにガス供給を停止するのではなく、告知・勧告が先行する。\n\nA：技術基準不適合を理由とした直ちのガス供給停止は規定されておらず、告知・勧告が先行する手続き。\nC：需要家への告知は経済産業大臣への報告・大臣指示を待たずにガス事業者が直接行うべきもの。\nD：事業者が需要家の同意なく消費機器を勝手に修理・交換する権限はなく、法的根拠もない。\n\n【頻出】技術基準不適合発見時の対応手順（告知→勧告→必要に応じてガス供給停止の検討）は試験頻出の手続き問題。「直ちに供給停止」は誤答の典型。\n【混同注意】「保安上の危険がある場合の供給停止（緊急時）」と「技術基準不適合発見時の告知・勧告（通常時）」は適用場面が異なる。"
