"explanation": "ガス事業法は主に一般ガス導管事業者等が供給する都市ガス（天然ガス・ナフサガス等を原料とした製造ガス）の供給・保安を規制する法律。液石法（液化石油ガスの保安の確保及び取引の適正化に関する法律）は主にプロパン・ブタン等のLPガスの保安・取引を規制する法律。異なる法律が適用される二つの分野。\n\nB：LPガスにはガス事業法ではなく液石法が適用される。ガス事業法のみが両方に適用されるわけではない。\nC：適用関係が逆になっており誤り。都市ガス＝ガス事業法、LPガス＝液石法が正しい対応。\nD：両法律は対象ガスの種類・規制内容が異なる別個の法律であり、同一内容ではない。\n\n【頻出】ガス事業法（都市ガス）と液石法（LPガス）の適用区分は試験最頻出の法令問題。ガス種と適用法令の対応を確実に覚える。\n【混同注意】「都市ガス用設備にはガス事業法」「LPガス設備には液石法」という対応は試験全体を通じて重要な基礎知識。"
