"explanation": "ガス事業法上、ガス小売事業者の登録には有効期間（期限）の定めがない。一度登録を受ければ、廃止・取消・欠格事由該当等の登録消滅事由が生じない限り、登録は継続して有効となる（更新手続きが不要）。これは免許・許可とは異なる登録制の特徴の一つ。\n\nA：5年の有効期間・更新手続きという規定はガス小売事業者の登録には存在しない。\nB：3年の有効期間という規定も存在しない。\nD：毎年更新が必要という規定もなく、更新不要で継続有効が正しい。\n\n【頻出】登録（有効期間なし・更新不要）と許可（有効期間あり・更新必要な場合がある）の違いは試験頻出の比較問題。\n【混同注意】「登録＝有効期間なし」という登録制の特性は、宅建業の免許（5年更新）等他の資格・許認可制度との比較でひっかけとして出題される。"
