"answer": 0,
"explanation": "ガス事業法上、使用前検査（完成検査）は特定のガス工作物について経済産業大臣または登録検査機関が行う外部の法定検査。自主検査はガス事業者自身が使用開始前・定期的に実施する内部検査。両者は実施主体・法的位置付けが異なる別個の検査制度。\n\nB：使用前検査（外部の法定検査）と自主検査（内部検査）は実施主体・目的が異なる別制度であり、「実質的な違いはない」は誤り。\nC：特定のガス工作物については使用前検査（完成検査）が法令上義務付けられており、任意ではない。\nD：自主検査はガス事業者自身が行うものであり、登録検査機関のみに委ねるわけではない。\n\n【頻出】使用前検査（外部・法定）と自主検査（内部・事業者実施）の区別は試験頻出の比較問題。\n【混同注意】「検査の主体（誰が行うか）」で両者を区別することが最も確実な方法。外部＝使用前検査、内部＝自主検査という対応を覚える。"
