"answer": 1,
"explanation": "ガス消費機器設置工事監督者はガス事業法に基づく資格であり、都市ガスの消費機器（給湯器・ガスこんろ・ガス暖房機等）の設置・変更工事の監督・施工管理を行う資格者。経済産業大臣登録の講習修了等で取得できる。\n\nA：ガス消費機器設置工事監督者は都市ガスの消費機器設置工事に関する資格であり、LPガス専用ではない。LPガスは液化石油ガス設備士が対応する。\nC：ガス消費機器設置工事監督者とガス主任技術者免状は別の資格制度であり、兼任義務もない。\nD：ガス消費機器設置工事監督者の取得要件に甲種ガス主任技術者免状の保有は必要とされていない。\n\n【頻出】ガス消費機器設置工事監督者（都市ガス・消費機器設置）と液化石油ガス設備士（LPガス・設備工事）の役割・適用ガス種の違いは試験頻出の比較問題。\n【混同注意】「都市ガス消費機器＝ガス消費機器設置工事監督者」「LPガス設備＝液化石油ガス設備士」という資格と対象ガスの対応を確実に覚える。"
