"answer": 1,
"explanation": "ヒヤリハット（Near Miss）とは「危うく事故になりそうだった」「ヒヤリとした・ハッとした」経験のことをいい、重大事故には至らなかった軽微な危険事象。ハインリッヒの法則（1件の重大事故の背後に29件の軽傷事故・300件のヒヤリハットがある）に基づき、ヒヤリハットを積極的に収集・分析して対策を講じることが重大事故の予防につながる。\n\nA：ヒヤリハットは事故が発生した場合の事後処理ではなく、事故未満の危険事例（ニアミス）の記録・活用。\nC：ヒヤリハットを積極的に報告・共有することが安全文化の醸成・重大事故予防に有効。「報告推奨されない」は誤り。\nD：ヒヤリハット報告の月次提出を義務付ける法令上の規定は一般的に存在しない（一部業界の自主的な取り組み）。\n\n【頻出】ヒヤリハットの定義（重大事故未満の危険事例）とハインリッヒの法則（1:29:300）・活用目的（重大事故予防）は試験頻出の安全管理知識。\n【混同注意】「ヒヤリハット（事故未満）」と「事故（発生済み）」の区別、および積極的な報告が安全向上につながるという考え方を正確に理解する。"
