"answer": 0,
"explanation": "ボイル・シャルルの法則 P₁V₁/T₁＝P₂V₂/T₂ を適用する。P₁＝2気圧、T₁＝27℃＝300 K、V₁＝V、P₂＝1気圧、T₂＝0℃＝273 K。V₂＝V×(P₁/P₂)×(T₂/T₁)＝V×(2/1)×(273/300)＝V×2×0.91＝約1.82V。\n\nB：0.55Vは体積が大幅に減少する計算であり、圧力低下（2→1気圧）による体積増加の効果を無視した誤り。\nC：2.00Vは温度換算（273/300≒0.91）を考慮せず、圧力比（2→1）のみで計算した場合の値（V×2＝2V）。\nD：0.91Vは圧力比（2→1気圧：体積2倍）を無視して温度比（273/300≒0.91）のみで計算した誤り。\n\n【頻出】ボイル・シャルルの法則を用いた体積換算計算（標準状態換算）はガス計量・供給計算の基礎として頻出。絶対温度（K）への換算を忘れないこと。\n【混同注意】圧力増加→体積減少、温度増加→体積増加、というそれぞれの効果の方向を確認してから計算する。"
