    "answer": 1,
    "explanation": "フェイルセーフ（Fail Safe）とは、システムの一部が故障・誤作動した場合でも、全体としては安全な状態（危険が発生しない状態）に移行するよう設計する概念。例：熱電対が断線（故障）→電磁弁が閉（ガス遮断）という「故障→安全方向」の設計。\n\nA：故障が危険な状態を作り出すのは「フェイルセーフ」ではなく「フェイルデンジャー（Fail Danger）」であり、設計として避けるべき状態。\nC：フェイルセーフはガス保安設計の重要な原則として積極的に採用すべき概念。コスト面のデメリットがあっても安全確保上必要。\nD：フェイルセーフはガス設備（安全弁・電磁弁・自動遮断装置等）にも広く適用される設計概念。電気系統専用ではない。\n\n【頻出】フェイルセーフの定義（故障→安全方向への移行）は安全設計概念として試験頻出。熱電対断線→電磁弁閉（ガス遮断）という具体例とセットで覚える。\n【混同注意】「フェイルセーフ（故障→安全）」と「フールプルーフ（人的ミス→危険防止）」は異なる安全設計概念であることも確認する。"
