    "answer": 1,
    "explanation": "保安文化（Safety Culture）とは、IAEA（国際原子力機関）が提唱した概念で、組織内のすべての人が安全を最優先する価値観・態度・行動規範を共有し、継続的な保安水準の改善に取り組む組織風土・文化をいう。ガス・エネルギー分野でも重要な概念。\n\nA：保安文化は事後補償ではなく「事故の未然防止」を中心とした組織的な安全への取り組みを指す。\nC：保安文化は経営層から現場作業員まで組織全員が意識・実践すべきものであり、特定層のみへの限定はない。\nD：保安文化が高い組織ではヒヤリハットを積極的に報告・共有する文化が根付くため、報告件数は増加する傾向がある（隠ぺい・未報告が減少）。ゼロに近いのは良好な状態ではなく、むしろ報告されていない可能性を示す。\n\n【頻出】保安文化の定義（全員参加・安全最優先・継続改善）とヒヤリハット積極報告との関連は試験頻出の安全管理論点。\n【混同注意】「ヒヤリハット件数ゼロ＝良い文化」という誤解をしないこと。積極的な報告・共有が保安文化向上の指標となる。"
