    "explanation": "安全装置（立消え安全装置・過熱防止装置・感震遮断装置等）の部品（熱電対・感圧素子・バイメタル等）は経年使用により劣化・感度変化・固着等の不具合が生じる可能性がある。このため定期的な作動試験・機能確認（模擬的な異常状態による作動確認等）を実施し、正常に機能することを保安規程に定めた周期で確認することが必要。\n\nA：一度確認したからといって以降の点検が不要にはならない。経年劣化により安全装置の信頼性は低下する可能性があり、定期的な確認が必要。\nC：安全装置の機能確認・作動試験は保安規程に基づきガス事業者・工事業者が実施する事項であり、メーカー専用ではない。\nD：実際の危険状態（実際のガス漏れ等）を意図的に作り出して試験することは危険であり、一般的には模擬的な方法（試験スイッチの操作・模擬信号の入力等）で作動確認を行う。\n\n【頻出】安全装置の定期的な作動試験・機能確認の重要性は保安管理の基本として試験頻出。「一度確認で以降不要」という選択肢は典型的なひっかけ。\n【混同注意】実際の危険状態での試験（危険）と模擬的な方法による試験（安全・実施可能）の区別を明確にすること。"
