    "explanation": "凍結防止ヒーター（電気ヒーター）への電力供給が見込めない場合、配管内の水がそのまま凍結し熱交換器・配管の破損につながる。この場合の有効な凍結対策は給湯器本体・配管の水抜き（水を排出して管内に水が残らない状態にする）を実施すること。水がなければ凍結は発生しない。\n\nA：凍結が発生してから修理依頼では熱交換器・配管の破損が生じており、多大な修理費用が発生する。事前の予防措置が重要。\nC：−5℃でも機器の設置状況（風当たり・断熱の有無）によっては凍結が発生する。「−5℃程度では不要」という判断は誤り。\nD：水抜きは給湯器の設計上想定された操作であり、正しく実施すれば機器を損傷しない。「損傷する」は誤り。断熱材のみでは極低温では不十分な場合がある。\n\n【頻出】凍結防止の代替手段（電力なし→水抜き実施）は実務的な保安知識として頻出。水抜きが「安全な操作である」という認識も重要。\n【混同注意】「凍結防止ヒーター（電力使用）」と「水抜き（電力不要）」は別々の凍結対策手段であり、電力供給不可時は水抜きが有効な代替手段となることを理解する。"
